from pathlib import Path
import json,re,struct,hashlib,subprocess
out=Path('.work/rot3-20261116');report={}
def pe(path):
 data=path.read_bytes();at=struct.unpack_from('<I',data,0x3c)[0];count=struct.unpack_from('<H',data,at+6)[0];opt=at+24;size=struct.unpack_from('<H',data,at+20)[0];base=struct.unpack_from('<Q',data,opt+24)[0];sec={}
 for i in range(count):
  h=opt+size+40*i;name=data[h:h+8].rstrip(b'\0').decode();vs,rva,rawsize,raw=struct.unpack_from('<IIII',data,h+8);sec[i+1]={'name':name,'rva':rva,'raw':raw,'size':rawsize}
 return data,base,sec
for kind in ('baseline','candidate'):
 sym=out/(kind+'-windows-symbols/bin/sigma.exe');timed=out/(kind+'-windows/bin/sigma.exe');data,base,secs=pe(sym);actual,abase,asecs=pe(timed);text=(out/(kind+'-pdb-symbols.txt')).read_text();rows=[]
 for m in re.finditer(r'S_[LG]PROC32[^\n]*`([^`]+)`\n\s*parent[^\n]*addr = (\d+):(\d+), code size = (\d+)',text):
  name,sec,offset,size=m.groups();sec=int(sec);offset=int(offset);size=int(size);rows.append({'name':name,'section':sec,'offset':offset,'bytes':size})
 targets=[r for r in rows if 'runOperationsLoop__' in r['name']];print(kind,'loop symbols',targets)
 for row in targets:
  section=secs[row['section']];begin=section['raw']+row['offset'];code=data[begin:begin+row['bytes']];prefix=code[:32];matches=[];i=actual.find(prefix)
  while i>=0:matches.append(i);i=actual.find(prefix,i+1)
  row['prefix32_matches_timed_file_offsets']=matches
  if len(matches)==1:
   found=matches[0];row['all_function_bytes_identical_in_timed']=actual[found:found+len(code)]==code
   tsec=next(s for s in asecs.values() if s['raw']<=found<s['raw']+s['size']);row['timed_va']=abase+tsec['rva']+found-tsec['raw']
  row['symbol_va']=base+section['rva']+row['offset'];row['sha256']=hashlib.sha256(code).hexdigest()
  cmd=['llvm-objdump','-d','--x86-asm-syntax=intel','--no-show-raw-insn','--start-address='+hex(row['symbol_va']),'--stop-address='+hex(row['symbol_va']+row['bytes']),str(sym)]
  r=subprocess.run(cmd,capture_output=True);(out/(kind+'-'+row['name']+'.asm')).write_bytes(r.stdout)
 report[kind]={'loops':targets,'functions':rows}
(out/'windows-code-map.json').write_text(json.dumps(report,indent=2)+'\n');print('maps saved')

