from pathlib import Path
import json,re,subprocess,hashlib,difflib
out=Path('.work/rot3-20261116');maps=json.loads((out/'windows-code-map.json').read_text());report={}
def parse(text,start,end):
 result=[]
 for line in text.splitlines():
  m=re.match(r'^\s*([0-9a-f]+):\s+(.+)$',line)
  if not m:continue
  address=int(m[1],16);ins=m[2].split('#')[0].strip();ins=re.sub(r'\s*<[^>]+>','',ins);mnemonic=ins.split()[0]
  if mnemonic=='call' or mnemonic.startswith('j'):
   dest=re.search(r'0x([0-9a-f]+)',ins)
   if dest:
    target=int(dest[1],16);replacement='INTERNAL+'+hex(target-start) if start<=target<end else 'EXTERNAL';ins=ins[:dest.start()]+replacement+ins[dest.end():]
  ins=re.sub(r'rip\s*([+-])\s*0x[0-9a-f]+',r'rip \1 EXTERNAL',ins)
  result.append((address-start,ins))
 return result
for kind in ('baseline','candidate'):
 report[kind]=[]
 for row in maps[kind]['loops']:
  start=row['timed_va'];end=start+row['bytes'];binary=out/(kind+'-windows/bin/sigma.exe');r=subprocess.run(['llvm-objdump','-d','--x86-asm-syntax=intel','--no-show-raw-insn','--start-address='+hex(start),'--stop-address='+hex(end),str(binary)],capture_output=True);text=r.stdout.decode();name=kind+'-'+row['name']+'-timed.asm';(out/name).write_text(text)
  symtext=(out/(kind+'-'+row['name']+'.asm')).read_text();a=parse(symtext,row['symbol_va'],row['symbol_va']+row['bytes']);b=parse(text,start,end);equal=a==b
  stat={'name':row['name'],'bytes':row['bytes'],'symbol_va':row['symbol_va'],'timed_va':start,'prefix32_unique':len(row['prefix32_matches_timed_file_offsets'])==1,'raw_bytes_identical':row['all_function_bytes_identical_in_timed'],'instruction_rows':len(b),'normalized_address_operand_comparison_identical':equal,'normalization_limit':'Internal branch target offsets and instruction/register/constant operands preserved; external branch/call identities and RIP data target identities are abstracted, not independently proved.','normalized_sha256':hashlib.sha256(json.dumps(b).encode()).hexdigest()}
  if not equal:stat['first_differences']=list(difflib.unified_diff([str(x) for x in a],[str(x) for x in b]))[:40]
  report[kind].append(stat);print(kind,row['name'],len(b),'normalized equal',equal)
(out/'windows-timed-symbol-comparison.json').write_text(json.dumps(report,indent=2)+'\n')
